  return `${pageIntro('OS ERROS SÃO PISTAS','Aprenda com o que faltou','O histórico mostra evidências. Uma resposta sozinha nem sempre revela a causa.')} ${errors.length?`<div class="stats-grid three"><div class="stat-card"><span class="stat-number">${errors.length}</span><strong>Primeiras tentativas incorretas</strong></div><div class="stat-card"><span class="stat-number">${groups.length}</span><strong>Fórmulas para observar</strong></div><div class="stat-card"><span class="stat-number">${groups[0]?esc(groups[0].f.short):'—'}</span><strong>Maior número de erros</strong></div></div><div class="error-grid">${groups.map(g=>`<section class="panel error-card"><div class="panel-heading"><h2>${g.f.name}</h2><span class="error-count">${g.wrong.length} erros / ${g.all.length}</span></div>${equationMarkup(g.f)}<p>${g.wrong.length>=3?`Você errou ${g.wrong.length} primeiras tentativas envolvendo esta fórmula. Revise a condição de aplicação e compare as resoluções.`:'Ainda há poucas tentativas para apontar uma dificuldade recorrente. Uma revisão breve pode ajudar.'}</p><details><summary>Investigar as respostas</summary>${g.wrong.slice(-5).reverse().map(a=>`<article class="error-evidence"><small>${new Date(a.at).toLocaleDateString('pt-BR')} · ${LEVELS[a.level]}</small><p>${esc(a.question?.prompt||g.f.name)}</p><p><strong>Sua resposta:</strong> ${esc(a.question?displayedResponse(a.question,a.input):a.input)}</p><p>${esc(a.question?diagnose(a.question,a.input):'Revise a interpretação e as unidades.')}</p>${a.question?`<details><summary>Ver resolução</summary>${solutionMarkup(a.question)}</details>`:''}</article>`).join('')}</details><div class="button-row">${button('Gerar 5 semelhantes','review-five','primary',`data-id="${g.f.id}"`)}${linkButton('Rever conceito',`formulas/${g.f.id}`,'secondary')}${linkButton('Observar simulação','lab','ghost')}</div></section>`).join('')}</div>`:emptyState('Seu mapa de revisão aparecerá aqui','Responda questões para descobrir quais assuntos precisam de mais atenção.',linkButton('Começar a praticar','arena'))}`;
